 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])

    # The color-1 object below the separator is the reference shape.
    ref_color = 1
    ref_cells = [(r, c) for r in range(h) for c in range(w)
                 if grid[r][c] == ref_color and r > 5]
    if not ref_cells:
        raise ValueError('missing lower reference object')
    r0, r1 = min(r for r, c in ref_cells), max(r for r, c in ref_cells)
    c0, c1 = min(c for r, c in ref_cells), max(c for r, c in ref_cells)
    ref = [[1 if (r, c) in set(ref_cells) else 0
            for c in range(c0, c1 + 1)] for r in range(r0, r1 + 1)]

    # Of the upper objects, use the rightmost (neither the reference-color
    # copy nor the central color-2 distractor).
    candidates = {}
    for r in range(6):
        for c in range(w):
            v = grid[r][c]
            if v not in (0, 1, 2, 5):
                candidates.setdefault(v, []).append((r, c))
    if not candidates:
        raise ValueError('missing upper candidate')
    color = max(candidates, key=lambda v: max(c for r, c in candidates[v]))
    cells = candidates[color]
    ar0, ar1 = min(r for r, c in cells), max(r for r, c in cells)
    ac0, ac1 = min(c for r, c in cells), max(c for r, c in cells)
    obj = [[color if (r, c) in set(cells) else 0
            for c in range(ac0, ac1 + 1)] for r in range(ar0, ar1 + 1)]

    # Shift the lower reference upward by six rows. Stack the selected shape
    # on the side of color-5 divider indicated by its color.
    rr0, rr1 = r0 - 6, r1 - 6
    if color < 5:
        or0, or1 = rr0 - len(obj), rr0 - 1
    else:
        or0, or1 = rr1 + 1, rr1 + len(obj)
    out_h = max(9, rr1 + 1, or1 + 1)
    out = [[0] * w for _ in range(out_h)]
    for i, row in enumerate(ref):
        for j, v in enumerate(row):
            if v:
                out[rr0 + i][c0 + j] = v
    for i, row in enumerate(obj):
        for j, v in enumerate(row):
            if v:
                out[or0 + i][c0 + j] = v
    return out
